sn_aia_tool.script:
(function(inputs, _agentic_context_) {
    var CAP_ID = '5817eb2b9f36121029ead63a6a0a1c7c'; // Web Search
    var NEWS_DOMAINS = 'economictimes.indiatimes.com,livemint.com,business-standard.com,' +
                       'thehindubusinessline.com,moneycontrol.com,financialexpress.com,' +
                       'thehindu.com,reuters.com,bseindia.com,nseindia.com';

    var company = (inputs.company_name || '').toString().trim();
    if (!company) return JSON.stringify({ status: 'error', message: 'company_name is required' });

    var today = new GlideDate().getByFormat('dd MMM yyyy');

    var searches = [
        {
            key: 'company_snapshot', domains: '', links: false,
            q: company + ' as of ' + today + ': share price NSE BSE, market capitalisation, 52 week range, ' +
               'latest quarterly revenue and net profit with YoY change, debt position, credit rating, ' +
               'major recent orders, leadership changes, analyst rating and target price'
        },
        {
            key: 'latest_news', domains: NEWS_DOMAINS, links: true,
            q: 'Latest business news about ' + company + ' published in the last 7 days up to ' + today +
               '. List up to 6 separate news articles, newest first. For each give the publication date, ' +
               'headline, publisher and a two line summary.'
        },
        {
            key: 'risk_alerts', domains: NEWS_DOMAINS, links: true,
            q: company + ' news in the last 90 days about payment default, debt stress, insolvency or NCLT, ' +
               'credit rating downgrade, fraud, tax or ED raid, regulatory penalty, labour strike or plant shutdown. ' +
               'Give the publication date and publisher for each. If none, say no adverse news found.'
        }
    ];

    var out = { status: 'success', company: company, searched_on: today, results: {} };
    var gotAny = false;

    for (var i = 0; i < searches.length; i++) {
        var s = searches[i];
        var r = runSearch(s.q, s.domains, s.links);
        // Retry on the open web only if the restricted search returned nothing
        if (s.domains && !r.answer) {
            var retry = runSearch(s.q, '', s.links);
            if (retry.answer) r = retry;
        }
        out.results[s.key] = r;
        if (r.answer) gotAny = true;
    }

    if (!gotAny) out.status = 'no_results';
    out.instructions = 'In latest_news and risk_alerts each fact is followed by (Link: url | publisher). ' +
        'Use that url as the Link for that news item only. Copy urls exactly. Never invent or reuse links.';
    return JSON.stringify(out);

    // ---------------- helpers ----------------

    function runSearch(q, domains, withLinks) {
        try {
            var payload = { query: q };
            if (domains) payload.search_domains = domains;

            var response = sn_one_extend.OneExtendUtil.execute({
                executionRequests: [{ payload: payload, capabilityId: CAP_ID }]
            });
            var caps = (response && response.capabilities) || {};
            var res = caps[CAP_ID] && caps[CAP_ID].response;

            if (Array.isArray(res) && res.length > 0 && res[0].answer) {
                var chunks = res[0].groundingChunks || [];
                var sources = [];
                for (var c = 0; c < chunks.length; c++) {
                    sources.push({ n: c + 1, publisher: chunks[c].title || '', url: chunks[c].url || '' });
                }
                return {
                    query: q,
                    answer: withLinks ? inlineLinks(res[0].answer, sources) : stripMarkers(res[0].answer),
                    error: null
                };
            }

            for (var id in caps) {
                if (typeof caps[id].response === 'string' && caps[id].response) {
                    return { query: q, answer: stripMarkers(caps[id].response), error: null };
                }
            }
            return { query: q, answer: '', error: 'Empty response' };

        } catch (e) {
            gs.error('[CLM VRI] Search failed for "' + q + '": ' + (e.message || e));
            return { query: q, answer: '', error: String(e.message || e) };
        }
    }

    // [1] / [1, 2] -> "(Link: url | publisher)" right next to the fact
    function inlineLinks(text, sources) {
        return (text || '')
            .replace(/[\u200B-\u200D\uFEFF]/g, '')
            .replace(/\s*\[cite:[^\]]*\]?/gi, '')
            .replace(/\s*\[(\d+(?:\s*,\s*\d+)*)\]/g, function(m, nums) {
                var links = [];
                nums.split(',').forEach(function(n) {
                    var src = sources[parseInt(n.trim(), 10) - 1];
                    if (src && src.url) links.push('(Link: ' + src.url + ' | ' + src.publisher + ')');
                });
                return links.length ? ' ' + links.join(' ') : '';
            })
            .trim();
    }

    function stripMarkers(text) {
        return (text || '')
            .replace(/[\u200B-\u200D\uFEFF]/g, '')
            .replace(/\s*\[cite:[^\]]*\]?/gi, '')
            .replace(/\s*\[\d+(?:\s*,\s*\d+)*\]/g, '')
            .trim();
    }

})(inputs, _agentic_context_);

